try:
    from inspect import getfullargspec as get_args
except ImportError:
    from inspect import getargspec as get_args
from functools import wraps
from robot.api import logger

TABLE_TEMPLATE = '''<table bgcolor="yellow" border=1>
                        <tr><td>Keyword</td><td>{}</td></tr>
                        <tr><td>Library</td><td>{}</td></tr>
                        <tr><td>Parameters</td><td>{}</td></tr>
                        <tr><td>Default parameters</td><td>{}</td></tr>
                    </table>'''


def _get_defaults(arg):
    if arg.defaults:
        defaults = dict(list(zip(reversed(arg.args), reversed(arg.defaults))))
        return ['{}={}'.format(key, value) for key, value in list(defaults.items())]
    return ''


def log_method_name(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        keyword_name = f.__name__.replace('_', ' ').title()
        library_name = f.__module__

        arg_list = []
        default_args = _get_defaults(get_args(f))
        for arg in list(args):
            if isinstance(arg, str):
                arg_list.append(arg)
        for key, value in list(kwargs.items()):
            arg_list.append('{}={}'.format(key, value))

        logger.write(TABLE_TEMPLATE.format(keyword_name, library_name, arg_list, default_args), level='HTML', html=True)

        result = f(*args, **kwargs)
        logger.write(
            '<span style="color:blue"><b>{}.{} | Result: {}</span></b>'.format(library_name, keyword_name, result),
            level='HTML',
            html=True,
        )
        return result

    return wrapper
